<?php require '../config/database.php';require '../includes/functions.php';$in=$_GET['check_in']??date('Y-m-d');if(!$in)$in=date('Y-m-d');$out=$_GET['check_out']??date('Y-m-d',strtotime($in.' +1 day'));if(!$out)$out=date('Y-m-d',strtotime($in.' +1 day'));$guests=max(1,(int)($_GET['guests']??1));$sql="SELECT * FROM rooms WHERE status='available' AND capacity>=? AND id NOT IN(SELECT room_id FROM bookings WHERE status IN ('pending','confirmed') AND NOT(check_out<=? OR check_in>=?)) ORDER BY price_per_night";$p=[$guests,$in,$out];$st=$pdo->prepare($sql);$st->execute($p);$rooms=$st->fetchAll();$page_title='Rooms - LuxeStay';include '../includes/header.php';?>
<div class="container page-hero"><h1>Find your room</h1><p class="muted">Choose the stay that fits your trip. Rooms reserved or approved for your selected dates are hidden.</p><form class="filter-bar"><div><label>Check-in</label><input class="input" type="date" name="check_in" value="<?=e($in)?>"></div><div><label>Check-out</label><input class="input" type="date" name="check_out" value="<?=e($out)?>"></div><div><label>Guests</label><select class="select" name="guests"><?php for($i=1;$i<=6;$i++):?><option <?=$i==$guests?'selected':''?>><?=$i?></option><?php endfor;?></select></div><div></div><button class="btn btn-primary">Search</button></form><div class="grid cards-3"><?php if(!$rooms):?><div class="card empty" style="grid-column:1/-1">No available rooms match your search.</div><?php endif;?><?php foreach($rooms as $r):?><article class="room-card"><img src="<?=e($r['image_url'])?>" alt=""><div class="room-body"><div class="room-top"><h3><?=e($r['name'])?></h3><div class="price">₱<?=number_format($r['price_per_night'],0)?></div></div><p class="muted"><?=e($r['short_description'])?></p><div class="chips"><span class="chip"><?=e($r['room_type'])?></span><span class="chip"><?=e($r['capacity'])?> guests</span></div><a class="btn btn-primary" href="<?=url('rooms/view.php?id='.$r['id'].'&check_in='.urlencode($in).'&check_out='.urlencode($out).'&guests='.$guests)?>">View & book</a></div></article><?php endforeach;?></div></div><?php include '../includes/footer.php';?>